message.content:
To expose runtime metrics to the client HUD in a protocol-first way while maintaining simulation authority in the runtime, we need to:

1.  **Extend the Protocol**: Add a new `runtime.metrics` server message type to `packages/protocol/src/messages.ts`.
2.  **Update Runtime Server**: Modify `apps/game-runtime/src/runtime/GameRuntimeServer.ts` to include metrics in the `session.state` payload and emit periodic updates.
3.  **Update Client**: Modify `apps/game-client/src/App.tsx` to consume the new metrics and display them in the HUD.
4.  **Add Contract Tests**: Update `apps/game-runtime/test/ui-contract.integration.test.ts` to verify the new message structure.

Here is the minimal change set:

### 1. Protocol Definition
**File**: `packages/protocol/src/messages.ts`

Add the `RuntimeMetrics` type and the new `runtime.metrics` message variant to `ServerMessage`.

```typescript
// packages/protocol/src/messages.ts

// ... existing imports ...

export type RuntimeMetrics = {
  turnsTotal: number;
  invalidOutputCount: number;
  actionAppliedCount: number;
  actionRejectedCount: number;
  queuedActions: number;
};

// ... existing types ...

export type ServerMessage =
  | {
      version: Version;
      type: "session.state";
      payload: {
        phase: SessionPhase;
        paused: boolean;
        preparedSeed: number | null;
        threadIds: { gameplayByAgentId: Record<string, string>; builder?: string };
        connected: boolean;
        runtime: {
          model: string | null;
          effort: TurnEffort;
          tickMs: number;
          schedulerMs: number;
          maxQueuedActionsBeforeTurn: number;
          availableModels: RuntimeModelOption[];
          metrics: RuntimeMetrics; // Added
        };
      };
    }
  | {
      version: Version;
      type: "runtime.metrics"; // Added
      payload: RuntimeMetrics;
    }
  // ... rest of ServerMessage union ...
```

### 2. Runtime Server Implementation
**File**: `apps/game-runtime/src/runtime/GameRuntimeServer.ts`

Update `sendSessionState` to include metrics and add a method to emit metrics updates.

```typescript
// apps/game-runtime/src/runtime/GameRuntimeServer.ts

// ... existing imports ...

// ... inside GameRuntimeServer class ...

  private sendSessionState(): void {
    this.emitMessage({
      version: PROTOCOL_VERSION,
      type: "session.state",
      payload: {
        phase: this.phase,
        paused: this.paused,
        preparedSeed: this.preparedSeed,
        threadIds: this.threadIds,
        connected: this.connected,
        runtime: {
          model: this.turnModel,
          effort: this.turnEffort,
          tickMs: runtimeConfig.tickMs,
          schedulerMs: runtimeConfig.schedulerMs,
          maxQueuedActionsBeforeTurn: runtimeConfig.maxQueuedActionsBeforeTurn,
          availableModels: this.availableModels,
          metrics: this.metrics.snapshot() // Added
        }
      }
    });
  }

  // Add this new method
  private sendMetricsUpdate(): void {
    this.emitMessage({
      version: PROTOCOL_VERSION,
      type: "runtime.metrics",
      payload: this.metrics.snapshot()
    });
  }

  // Update tick() to emit metrics periodically or on change
  private tick(): void {
    if (!this.simulation || this.phase !== "running") {
      return;
    }

    if (this.paused) {
      this.metrics.setQueueDepth(this.totalQueuedActions());
      this.sendMetricsUpdate(); // Added
      return;
    }

    this.simulation.tick();

    const agents = this.simulation.getState().agents.map((agent) => agent.id).sort();
    for (const agentId of agents) {
      const queue = this.actionQueueByAgent.get(agentId);
      const nextAction = queue?.shift();
      if (!nextAction) {
        continue;
      }
      const result = this.simulation.applyAction(agentId, nextAction);
      if (result.result === "applied") {
        this.metrics.onActionApplied();
      } else {
        this.metrics.onActionRejected();
      }
      this.emitMessage({
        version: PROTOCOL_VERSION,
        type: "agent.action",
        payload: {
          agentId,
          action: result.action,
          result: result.result,
          ...(result.reason ? { reason: result.reason } : {})
        }
      });
      void this.logReplay("action.applied", {
        agentId,
        action: result.action,
        result: result.result,
        reason: result.reason ?? null
      });
    }

    this.metrics.setQueueDepth(this.totalQueuedActions());
    this.sendWorldSnapshot();
    this.sendMetricsUpdate(); // Added
  }

  // Update requestGameplayTurn to emit metrics on turn completion
  private async requestGameplayTurn(agentId: string, isRetry: boolean, previousText: string): Promise<void> {
    // ... existing logic ...
    this.metrics.onTurnCompleted();
    // ... rest of logic ...
    this.sendMetricsUpdate(); // Added after metrics update
  }
```

